/**
 * context.ts — v9 Projection layer.
 *
 * Takes the full wrapped context from buildContext (engine layer) and shapes
 * it for the requesting agent based on salience thresholds.
 *
 * Three tiers:
 *   Focus      (score >= focus_threshold):   full value + full _meta
 *   Peripheral (score >= elide_threshold):   full value + minimal _meta
 *   Elided     (score <  elide_threshold):   value: null + minimal _meta + expand hint
 *
 * Override params:
 *   expand        — force specific keys to Focus (e.g. ["_shared.some_key"])
 *   elision       — "none" to disable elision entirely
 *   meta_threshold — override where full _meta kicks in (default: 0.5)
 *   focus_threshold — override focus threshold (default: 0.5)
 *   elide_threshold — override elide threshold (default: 0.1)
 *
 * Replaces: _salience synthetic view, _contested synthetic view, _context envelope.
 * All metadata now lives in _meta on the relevant entries.
 */

import { sqlite } from "https://esm.town/v/std/sqlite";
import { json, rows2objects } from "./utils.ts";
import {
  buildContext,
  celEval,
  evalCel,
  type BuildContextOptions,
  type WrappedEntry,
  type EntryMeta,
} from "./cel.ts";
import { isTimerLive } from "./timers.ts";
import { hasFullReadAccess, touchAgent, type AuthResult } from "./auth.ts";
import { BUILTIN_ACTIONS, OVERRIDABLE_BUILTINS } from "./invoke.ts";
import { minimalMeta } from "./meta.ts";

// ── ContextRequest ──────────────────────────────────────────────────────

export interface ContextRequest {
  /** Action detail level */
  depth?: "lean" | "full" | "usage";
  /** Return only these top-level sections */
  only?: string[];
  /** Include actions section (default true) */
  actions?: boolean;
  /** Include messages section (default true) */
  messages?: boolean;
  /** Message seq cursor — only return messages after this seq */
  messagesAfter?: number;
  /** Max messages to return (default 100, max 500) */
  messagesLimit?: number;
  /** Extra state scopes to include (e.g. "_audit") */
  include?: string[];

  // ── v9 shaping params ──

  /** Force specific keys to Focus tier: ["_shared.key1", "_agents.explorer"] */
  expand?: string[];
  /** Disable elision entirely: "none" */
  elision?: "none" | "auto";
  /** Threshold for full _meta (default 0.5) */
  focusThreshold?: number;
  /** Threshold below which values are elided (default 0.1) */
  elideThreshold?: number;
}

/** Parse a ContextRequest from URL search params or MCP tool params */
export function parseContextRequest(url: URL): ContextRequest {
  const req: ContextRequest = {};
  const depth = url.searchParams.get("depth");
  if (depth === "lean" || depth === "full" || depth === "usage") req.depth = depth;
  const only = url.searchParams.get("only");
  if (only) req.only = only.split(",").map((s) => s.trim()).filter(Boolean);
  const actions = url.searchParams.get("actions");
  if (actions === "false") req.actions = false;
  const messages = url.searchParams.get("messages");
  if (messages === "false") req.messages = false;
  const after = url.searchParams.get("messages_after");
  if (after) req.messagesAfter = parseInt(after);
  const limit = url.searchParams.get("messages_limit");
  if (limit) req.messagesLimit = parseInt(limit);
  const include = url.searchParams.get("include");
  if (include) req.include = include.split(",").map((s) => s.trim()).filter(Boolean);

  // v9 shaping
  const expand = url.searchParams.get("expand");
  if (expand) req.expand = expand.split(",").map((s) => s.trim()).filter(Boolean);
  const elision = url.searchParams.get("elision");
  if (elision === "none") req.elision = "none";
  const focusThreshold = url.searchParams.get("focus_threshold");
  if (focusThreshold) req.focusThreshold = parseFloat(focusThreshold);
  const elideThreshold = url.searchParams.get("elide_threshold");
  if (elideThreshold) req.elideThreshold = parseFloat(elideThreshold);

  return req;
}

// ── Shaping ─────────────────────────────────────────────────────────────

const DEFAULT_FOCUS_THRESHOLD = 0.5;
const DEFAULT_ELIDE_THRESHOLD = 0.1;

/** Minimal _meta for peripheral/elided tier — strip trajectory/provenance */
function trimMeta(meta: any, elided: boolean, expandHint?: string): any {
  const trimmed: any = {
    score: meta.score,
    revision: meta.revision,
    updated_at: meta.updated_at,
    elided,
  };
  if (elided && expandHint) {
    trimmed.expand = expandHint;
  }
  return trimmed;
}

/** Check if a scope.key is in the expand list */
function isExpanded(scope: string, key: string, expandSet: Set<string>): boolean {
  return (
    expandSet.has(`${scope}.${key}`) ||
    expandSet.has(`${scope}.*`) ||
    expandSet.has("*")
  );
}

/**
 * Shape a scope's entries by salience threshold.
 *
 * Focus:      full value + full _meta
 * Peripheral: full value + trimmed _meta (score, revision, updated_at)
 * Elided:     value: null + trimmed _meta + expand hint
 */
function shapeScope(
  scope: string,
  entries: Record<string, WrappedEntry>,
  focusThreshold: number,
  elideThreshold: number,
  expandSet: Set<string>,
  noElision: boolean,
): Record<string, any> {
  const shaped: Record<string, any> = {};

  for (const [key, entry] of Object.entries(entries)) {
    const score = entry._meta?.score ?? 0;
    const forceExpand = isExpanded(scope, key, expandSet);

    if (forceExpand || noElision || score >= focusThreshold) {
      // Focus tier: full value + full _meta
      shaped[key] = entry;
    } else if (score >= elideThreshold) {
      // Peripheral tier: full value + trimmed _meta
      shaped[key] = {
        value: entry.value,
        _meta: trimMeta(entry._meta, false),
      };
    } else {
      // Elided tier: null value + minimal _meta + expand hint
      shaped[key] = {
        value: null,
        _meta: trimMeta(
          entry._meta,
          true,
          `?expand=${scope}.${key}`,
        ),
      };
    }
  }

  return shaped;
}

// ── buildExpandedContext ─────────────────────────────────────────────────

/**
 * Build the agent-facing context response.
 *
 * v9: Returns wrapped { value, _meta } entries shaped by salience threshold.
 * All metadata (salience, provenance, trajectory, contested) lives in _meta.
 * No synthetic views, no _context envelope.
 */
export async function buildExpandedContext(
  roomId: string,
  auth: AuthResult,
  req: ContextRequest = {},
): Promise<Record<string, any>> {
  const depth = req.depth ?? "lean";
  const includeActions = req.actions !== false;
  const includeMessages = req.messages !== false;
  const includedScopes = req.include ?? [];

  // Shaping params
  const focusThreshold = req.focusThreshold ?? DEFAULT_FOCUS_THRESHOLD;
  const elideThreshold = req.elideThreshold ?? DEFAULT_ELIDE_THRESHOLD;
  const noElision = req.elision === "none";
  const expandSet = new Set(req.expand ?? []);

  // ── Engine layer: full wrapped context ──
  const ctx = await buildContext(roomId, {
    selfAgent: auth.agentId ?? undefined,
    allScopes: hasFullReadAccess(auth),
  });

  // ── Shape state scopes ──
  const stateOut: Record<string, any> = {};
  for (const [scope, entries] of Object.entries(ctx.state as Record<string, Record<string, WrappedEntry>>)) {
    // Strip _audit and _messages unless opted in
    if (scope === "_audit" && !includedScopes.includes("_audit")) continue;
    if (scope === "_messages" && !includedScopes.includes("_messages")) continue;
    // Skip system internals
    if (scope === "_actions" || scope === "_views" || scope === "_agents" || scope === "_config" || scope === "_help") continue;

    stateOut[scope] = shapeScope(
      scope, entries, focusThreshold, elideThreshold, expandSet, noElision,
    );
  }

  // ── Shape agents ──
  const agentsOut: Record<string, any> = {};
  for (const [id, entry] of Object.entries(ctx.agents as Record<string, WrappedEntry>)) {
    // Agents are always focus tier (important for coordination)
    agentsOut[id] = entry;
  }

  // ── Shape views ──
  const viewsOut: Record<string, any> = {};
  for (const [id, entry] of Object.entries(ctx.views as Record<string, WrappedEntry>)) {
    const score = entry._meta?.score ?? 0;
    if (noElision || score >= elideThreshold || isExpanded("_views", id, expandSet)) {
      viewsOut[id] = score >= focusThreshold || noElision
        ? entry
        : { value: entry.value, _meta: trimMeta(entry._meta, false) };
    } else {
      viewsOut[id] = {
        value: null,
        _meta: trimMeta(entry._meta, true, `?expand=_views.${id}`),
      };
    }
  }

  // ── Actions ──
  let actionsOut: Record<string, any> | undefined;

  if (includeActions) {
    actionsOut = {};

    // Custom actions from engine context (already wrapped with action _meta)
    for (const [id, entry] of Object.entries(ctx.actions as Record<string, WrappedEntry>)) {
      const actionValue = entry.value;
      const actionMeta = entry._meta as any;

      const shaped: any = {
        value: {
          available: actionValue.available ?? true,
          description: null as string | null,
        },
        _meta: actionMeta,
      };

      // Load full definition for description and depth-dependent fields
      try {
        const defResult = await sqlite.execute({
          sql: `SELECT value FROM state WHERE room_id = ? AND scope = '_actions' AND key = ?`,
          args: [roomId, id],
        });
        if (defResult.rows.length > 0) {
          const def = JSON.parse(defResult.rows[0][0] as string);
          shaped.value.description = def.description ?? null;

          if (depth === "full" || depth === "usage") {
            shaped.value.enabled = true;
            if (def.params) shaped.value.params = def.params;
            if (def.writes?.length > 0) shaped.value.writes = def.writes;
            if (def.if) shaped.value.if = def.if;
            if (def.scope && def.scope !== "_shared") shaped.value.scope = def.scope;
          }
        }
      } catch {}

      actionsOut[id] = shaped;
    }

    // Built-in actions (not in _actions scope — synthesize wrapped entries)
    for (const [id, def] of Object.entries(BUILTIN_ACTIONS)) {
      if (OVERRIDABLE_BUILTINS.has(id) && actionsOut[id]) continue;

      const builtinValue: any = {
        available: true,
        builtin: true,
        description: def.description,
      };
      if (depth === "full" || depth === "usage") {
        builtinValue.enabled = true;
        builtinValue.params = def.params ?? null;
      }

      actionsOut[id] = {
        value: builtinValue,
        _meta: {
          ...minimalMeta(0, "", 0),
          // Builtins have no audit trail — minimal meta
          invocations: 0,
          last_invoked_at: null,
          last_invoked_by: null,
          contested: [],
        },
      };
    }
  }

  // ── Messages ──
  let messagesOut: any;
  let sectionElided: string[] = [];

  if (includeMessages) {
    const messagesLimit = Math.min(req.messagesLimit ?? 100, 500);
    let msgSql = `SELECT scope, key, sort_key, value, revision, updated_at,
                  timer_json, timer_expires_at, timer_ticks_left, timer_tick_on,
                  timer_effect, timer_started_at, enabled_expr
                  FROM state WHERE room_id = ? AND scope = '_messages'`;
    const msgArgs: any[] = [roomId];
    if (req.messagesAfter) {
      msgSql += ` AND sort_key > ?`;
      msgArgs.push(req.messagesAfter);
    }
    msgSql += ` ORDER BY sort_key DESC LIMIT ?`;
    msgArgs.push(messagesLimit);
    const msgResult = await sqlite.execute({ sql: msgSql, args: msgArgs });
    let msgRows = rows2objects(msgResult).filter((r: any) => isTimerLive(r));
    msgRows.reverse();

    const recentMessages = msgRows.map((r: any) => {
      let parsed: any = {};
      try {
        parsed = JSON.parse(r.value);
      } catch {
        parsed = { body: r.value };
      }
      return { seq: r.sort_key, ...parsed };
    });

    // Update last_seen_seq
    if (auth.agentId && recentMessages.length > 0) {
      const maxSeq = Math.max(...recentMessages.map((m: any) => m.seq ?? 0));
      if (maxSeq > 0) {
        sqlite.execute({
          sql: `UPDATE state SET
                  value = json_set(value, '$.last_seen_seq', ?),
                  revision = revision + 1, updated_at = datetime('now')
                WHERE room_id = ? AND scope = '_agents' AND key = ?`,
          args: [maxSeq, roomId, auth.agentId],
        }).catch(() => {});
      }
    }

    // Count total for elision detection
    const totalMsgResult = await sqlite.execute({
      sql: `SELECT COUNT(*) as cnt FROM state WHERE room_id = ? AND scope = '_messages'`,
      args: [roomId],
    });
    const totalMessages = Number(rows2objects(totalMsgResult)[0]?.cnt ?? 0);
    const oldestSeq = recentMessages.length > 0 ? (recentMessages[0].seq ?? 0) : 0;

    messagesOut = {
      count: ctx.messages.count,
      unread: ctx.messages.unread,
      directed_unread: ctx.messages.directed_unread,
      recent: recentMessages,
    };

    if (totalMessages > messagesLimit) {
      messagesOut._meta = {
        total: totalMessages,
        returned: recentMessages.length,
        elided: true,
        expand: `?messages_after=0&messages_limit=${Math.min(totalMessages, 500)}`,
      };
    }
  } else {
    sectionElided.push("messages");
  }

  if (!includeActions) {
    sectionElided.push("actions");
  }

  // ── Assemble response ──
  let result: Record<string, any> = {
    state: stateOut,
    views: viewsOut,
    agents: agentsOut,
    ...(actionsOut !== undefined ? { actions: actionsOut } : {}),
    ...(messagesOut !== undefined ? { messages: messagesOut } : {}),
    self: ctx.self,
  };

  // ── Apply `only` filter ──
  if (req.only && req.only.length > 0) {
    const filtered: Record<string, any> = {};
    for (const s of req.only) {
      if (s in result) filtered[s] = result[s];
      if (s.startsWith("state.")) {
        const scope = s.slice(6);
        if (!filtered.state) filtered.state = {};
        if (ctx.state[scope]) {
          filtered.state[scope] = shapeScope(
            scope, ctx.state[scope], focusThreshold, elideThreshold, expandSet, noElision,
          );
        }
      }
    }
    if (result.self) filtered.self = result.self;
    for (const key of Object.keys(result)) {
      if (!(key in filtered) && key !== "self") sectionElided.push(key);
    }
    result = filtered;
  }

  // ── Shaping summary ──
  // Minimal envelope — just enough for the agent to understand what it got
  const shapingSummary: any = {
    focus_threshold: focusThreshold,
    elide_threshold: elideThreshold,
    elision: noElision ? "none" : "auto",
  };

  // Count shaped entries
  let focusCount = 0;
  let peripheralCount = 0;
  let elidedCount = 0;
  for (const scope of Object.values(stateOut)) {
    for (const entry of Object.values(scope as Record<string, any>)) {
      const e = entry as any;
      if (e?._meta?.elided) elidedCount++;
      else if (e?._meta?.score !== undefined && !e?._meta?.writers) peripheralCount++;
      else focusCount++;
    }
  }
  shapingSummary.state_entries = {
    focus: focusCount,
    peripheral: peripheralCount,
    elided: elidedCount,
    total: focusCount + peripheralCount + elidedCount,
  };

  if (sectionElided.length > 0) {
    shapingSummary.sections_elided = sectionElided;
  }

  result._shaping = shapingSummary;

  return result;
}

// ── CEL eval endpoint ───────────────────────────────────────────────────

export async function evalExpression(
  roomId: string,
  body: any,
  auth: AuthResult,
) {
  const expr = body.expr;
  if (!expr || typeof expr !== "string") {
    return json({ error: "expr string is required" }, 400);
  }
  touchAgent(roomId, auth.agentId);
  const ctx = await buildContext(roomId, {
    selfAgent: auth.agentId ?? undefined,
  });
  const result = await evalCel(roomId, expr, ctx);
  if (!result.ok) {
    return json(
      { error: "cel_error", expression: expr, detail: result.error },
      400,
    );
  }
  return json({ expression: expr, value: result.value });
}

/**
 * actions.ts — Action registration, deletion, and helpers.
 *
 * v9: Uses Environment-based CEL validation (validateExpression) with
 * structured error feedback including stage, hints, and lint warnings.
 */

import { sqlite } from "https://esm.town/v/std/sqlite";
import { json, rows2objects } from "./utils.ts";
import { validateExpression } from "./cel.ts";
import { parseTimer, validateTimer } from "./timers.ts";
import { appendStructuralEvent } from "./audit.ts";
import type { AuthResult } from "./auth.ts";

/**
 * Returns a map of "scope:key" → [actionId, ...] for any (scope, key) pair
 * that is the write target of two or more registered actions.
 */
export async function computeContestedTargets(roomId: string): Promise<Record<string, string[]>> {
  const result = await sqlite.execute({
    sql: `SELECT key, value FROM state WHERE room_id = ? AND scope = '_actions'`,
    args: [roomId],
  });
  const rows = rows2objects(result);

  const targets: Record<string, string[]> = {};
  for (const row of rows) {
    let def: any;
    try { def = JSON.parse(row.value as string); } catch { continue; }
    const writes = Array.isArray(def.writes) ? def.writes : [];
    for (const w of writes) {
      const scope = w.scope ?? "_shared";
      const key = w.key ?? null;
      if (!key) continue;
      const target = `${scope}:${key}`;
      if (!targets[target]) targets[target] = [];
      if (!targets[target].includes(row.key as string)) targets[target].push(row.key as string);
    }
  }

  const contested: Record<string, string[]> = {};
  for (const [target, ids] of Object.entries(targets)) {
    if (ids.length >= 2) contested[target] = ids;
  }
  return contested;
}

/** Validate a CEL field on an action definition, returning a structured error response or null if valid. */
function validateActionCel(field: string, expr: string): Response | null {
  const result = validateExpression(expr);
  if (result.valid) return null;
  if (result.stage === "eval" && result.error?.includes("No such key")) return null;
  return json({
    error: "invalid_cel",
    field,
    stage: result.stage,
    detail: result.error,
    hint: result.hint,
    source: result.source,
    help: result.help ?? "expressions",
  }, 400) as unknown as Response;
}

/** Collect lint warnings from all CEL fields on an action definition. */
function collectCelWarnings(body: any): string[] {
  const warnings: string[] = [];
  for (const field of ["if", "enabled", "result"]) {
    if (body[field]) {
      const result = validateExpression(body[field]);
      if (result.warnings) {
        for (const w of result.warnings) {
          warnings.push(`${field}: ${w}`);
        }
      }
    }
  }
  // Also lint write expressions
  if (Array.isArray(body.writes)) {
    for (const w of body.writes) {
      if (w.expr === true && typeof w.value === "string") {
        const result = validateExpression(w.value);
        if (result.warnings) {
          for (const warn of result.warnings) {
            warnings.push(`writes[].value: ${warn}`);
          }
        }
      }
    }
  }
  return warnings;
}

export async function registerAction(roomId: string, body: any, auth: AuthResult) {
  const id = body.id;
  if (!id) return json({ error: "id is required" }, 400);
  const scope = body.scope ?? "_shared";

  // Scope ownership enforcement
  if (scope !== "_shared") {
    if (!auth.authenticated) return json({ error: "authentication_required", message: `scoped actions require auth` }, 401);
    if (auth.kind !== "room" && !auth.grants.includes("*") && auth.agentId !== scope) {
      return json({ error: "identity_mismatch", message: `action scope "${scope}" requires authentication as "${scope}"` }, 403);
    }
  }

  // Validate expressions with structured feedback
  if (body.if) { const err = validateActionCel("if", body.if); if (err) return err; }
  if (body.enabled) { const err = validateActionCel("enabled", body.enabled); if (err) return err; }
  if (body.result) { const err = validateActionCel("result", body.result); if (err) return err; }

  if (body.timer) {
    const tv = validateTimer(body.timer);
    if (!tv.valid) return json({ error: "invalid_timer", detail: tv.error }, 400);
  }
  if (body.on_invoke?.timer) {
    const tv = validateTimer(body.on_invoke.timer);
    if (!tv.valid) return json({ error: "invalid_timer", field: "on_invoke.timer", detail: tv.error }, 400);
  }

  const writes = body.writes ?? [];
  if (!Array.isArray(writes)) return json({ error: "writes must be an array" }, 400);
  const registeredBy = scope !== "_shared" ? scope : (body.registered_by ?? (auth.authenticated ? auth.agentId : null));

  // Check for semantic changes on re-registration
  const writesJson = JSON.stringify(writes);
  const paramsJson = body.params ? JSON.stringify(body.params) : null;
  let reregistration: {
    previousRegistrant: string | null;
    writesChanged: boolean;
    paramsChanged: boolean;
    previousWrites: any[];
    invocationCount: number;
  } | null = null;

  const existing = await sqlite.execute({
    sql: `SELECT value FROM state WHERE room_id = ? AND scope = '_actions' AND key = ?`,
    args: [roomId, id],
  });
  if (existing.rows.length > 0) {
    let prevDef: any = {};
    try { prevDef = JSON.parse(existing.rows[0][0] as string); } catch {}
    const prevWritesJson = JSON.stringify(prevDef.writes ?? []);
    const prevParamsJson = prevDef.params ? JSON.stringify(prevDef.params) : null;
    const writesChanged = prevWritesJson !== writesJson;
    const paramsChanged = prevParamsJson !== paramsJson;

    if (writesChanged || paramsChanged) {
      let invocationCount = 0;
      try {
        const auditResult = await sqlite.execute({
          sql: `SELECT COUNT(*) as cnt FROM state WHERE room_id = ? AND scope = '_audit' AND value LIKE ?`,
          args: [roomId, `%"action":"${id}"%`],
        });
        invocationCount = Number(rows2objects(auditResult)[0]?.cnt ?? 0);
      } catch {}

      reregistration = {
        previousRegistrant: prevDef.registered_by ?? null,
        writesChanged, paramsChanged,
        previousWrites: prevDef.writes ?? [],
        invocationCount,
      };
    }
  }

  // Build timer state for initial registration
  let timerState: any = null;
  if (body.timer) {
    const cols = parseTimer(body.timer);
    timerState = {
      timer_json: cols.timer_json,
      timer_expires_at: cols.timer_expires_at,
      timer_ticks_left: cols.timer_ticks_left,
      timer_tick_on: cols.timer_tick_on,
      timer_effect: cols.timer_effect,
      timer_started_at: cols.timer_started_at,
    };
  }

  // Write to _actions scope
  const actionDef = {
    description: body.description ?? null,
    if: body.if ?? null,
    enabled: body.enabled ?? null,
    result: body.result ?? null,
    writes,
    params: body.params ?? null,
    scope,
    registered_by: registeredBy,
    timer: body.timer ?? null,
    on_invoke: body.on_invoke ?? null,
    _timer: timerState,
  };

  await sqlite.execute({
    sql: `INSERT INTO state (room_id, scope, key, value, version, revision, updated_at)
          VALUES (?, '_actions', ?, ?, '', 1, datetime('now'))
          ON CONFLICT(room_id, scope, key) DO UPDATE SET
            value = excluded.value, revision = state.revision + 1, updated_at = datetime('now')`,
    args: [roomId, id, JSON.stringify(actionDef)],
  });

  appendStructuralEvent(roomId, "register_action", auth.authenticated ? auth.agentId ?? null : null, {
    id, scope, description: body.description ?? null,
    if_expr: body.if ?? null, enabled_expr: body.enabled ?? null,
    writes, params: body.params ?? null,
  }).catch(() => {});

  // Build response
  const response: any = {
    id, room_id: roomId, scope, description: body.description ?? null,
    registered_by: registeredBy, writes, params: body.params ?? null,
  };
  if (body.if) response.if = body.if;
  if (body.enabled) response.enabled = body.enabled;
  if (body.result) response.result = body.result;
  if (body.timer) response.timer = body.timer;
  if (body.on_invoke) response.on_invoke = body.on_invoke;

  // Check contested targets
  const contested = await computeContestedTargets(roomId);
  const myWrites = writes.map((w: any) => `${w.scope ?? "_shared"}:${w.key ?? ""}`).filter((t: string) => !t.endsWith(":"));
  const myContested = myWrites.filter((t: string) => contested[t] && contested[t].length >= 2);

  const warnings: string[] = [];
  const warningDetails: Record<string, any> = {};

  if (myContested.length > 0) {
    warnings.push("competing_write_targets");
    warningDetails.contested_targets = myContested;
    warningDetails.competing_actions = myContested.map(t => ({ target: t, actions: contested[t] }));
  }

  if (reregistration) {
    warnings.push("action_redefined");
    warningDetails.redefinition = {
      previous_registrant: reregistration.previousRegistrant,
      writes_changed: reregistration.writesChanged,
      params_changed: reregistration.paramsChanged,
      invocation_count: reregistration.invocationCount,
      previous_writes: reregistration.previousWrites,
      risk: reregistration.invocationCount > 0 && reregistration.writesChanged
        ? "high — action has been invoked and write behavior changed"
        : reregistration.writesChanged
        ? "medium — write behavior changed"
        : "low — parameter schema changed but write targets unchanged",
    };
  }

  // Collect lint warnings from CEL expressions
  const celWarnings = collectCelWarnings(body);
  if (celWarnings.length > 0) {
    warnings.push("cel_lint");
    warningDetails.cel_warnings = celWarnings;
  }

  if (warnings.length > 0) {
    return json({ ...response, warning: warnings.length === 1 ? warnings[0] : warnings, ...warningDetails, help: "contested_actions" }, 201);
  }

  return json(response, 201);
}

export async function deleteAction(roomId: string, actionId: string, auth: AuthResult) {
  const existing = await sqlite.execute({
    sql: `SELECT value FROM state WHERE room_id = ? AND scope = '_actions' AND key = ?`,
    args: [roomId, actionId],
  });
  if (existing.rows.length === 0) return json({ error: "action not found" }, 404);
  let def: any = {};
  try { def = JSON.parse(existing.rows[0][0] as string); } catch {}
  const scope = def.scope ?? "_shared";
  if (scope !== "_shared") {
    if (auth.kind !== "room" && !auth.grants.includes("*") && auth.agentId !== scope) {
      return json({ error: "action_owned", message: `action "${actionId}" owned by "${scope}"`, owner: scope }, 403);
    }
  }
  await sqlite.execute({ sql: `DELETE FROM state WHERE room_id = ? AND scope = '_actions' AND key = ?`, args: [roomId, actionId] });
  appendStructuralEvent(roomId, "delete_action", auth.authenticated ? auth.agentId ?? null : null, { id: actionId }).catch(() => {});
  return json({ deleted: true, id: actionId });
}

/**
 * sampling.ts — View value sampling for temporal traces.
 *
 * Records periodic snapshots of view values into the audit log as
 * `kind: "sample"` entries. These entries power temporal sparklines
 * and history views on the dashboard.
 *
 * Sampling strategy:
 *   - Only views with render.temporal = true are sampled
 *   - At most one sample per view per SAMPLE_INTERVAL_MS (60s default)
 *   - Sampling is piggybacked on dashboardPoll — no separate cron
 *   - Samples are fire-and-forget, never block the poll response
 *   - Sample entries are indexed in log_index under scope "_samples"
 *
 * Sample log entry shape:
 *   { kind: "sample", ts, views: { [viewId]: value } }
 */

import { sqlite } from "https://esm.town/v/std/sqlite";
import { rows2objects } from "./utils.ts";
import { indexLogEntry } from "./schema-v8.ts";

const SAMPLE_INTERVAL_MS = 60_000; // 1 minute

// In-memory last-sample timestamps per room. Resets on cold start (acceptable).
const lastSampleTime = new Map<string, number>();

/**
 * Record view value samples if enough time has elapsed since the last sample.
 * Called from dashboardPoll after view evaluation.
 *
 * @param roomId - The room to sample
 * @param views - Evaluated views from the poll (with .value and .render)
 */
export async function maybeSampleViews(
  roomId: string,
  views: Array<{ id: string; value: any; render: any }>,
) {
  const now = Date.now();
  const lastTime = lastSampleTime.get(roomId) ?? 0;
  if (now - lastTime < SAMPLE_INTERVAL_MS) return;

  // Find temporal views
  const temporalViews = views.filter(v =>
    v.render?.temporal === true &&
    v.value !== undefined &&
    !(v.value && typeof v.value === "object" && v.value._error)
  );
  if (temporalViews.length === 0) return;

  // Record the sample
  lastSampleTime.set(roomId, now);

  try {
    // Get next audit seq
    const seqResult = await sqlite.execute({
      sql: `SELECT COALESCE(MAX(sort_key), 0) + 1 as next_seq FROM state WHERE room_id = ? AND scope = '_audit'`,
      args: [roomId],
    });
    const seq = Number(rows2objects(seqResult)[0]?.next_seq ?? 1);

    // Build sample entry
    const sampleValues: Record<string, any> = {};
    for (const v of temporalViews) {
      sampleValues[v.id] = v.value;
    }

    const entry = JSON.stringify({
      ts: new Date().toISOString(),
      kind: "sample",
      agent: "_system",
      ok: true,
      views: sampleValues,
    });

    // Append to audit log
    await sqlite.execute({
      sql: `INSERT INTO state (room_id, scope, key, sort_key, value, version, updated_at)
            VALUES (?, '_audit', ?, ?, ?, 1, datetime('now'))`,
      args: [roomId, String(seq), seq, entry],
    });

    // Index under _samples scope for each sampled view
    const affectedKeys = temporalViews.map(v => ({ scope: "_samples", key: v.id }));
    await indexLogEntry(roomId, seq, affectedKeys);
  } catch {
    // Fire and forget — never disrupt the poll
  }
}

/**
 * Query view value samples from the log.
 * Returns chronologically ordered samples for a specific view.
 */
export async function queryViewSamples(
  roomId: string,
  viewId: string,
  opts: { limit?: number; after?: number } = {},
): Promise<Array<{ seq: number; ts: string; value: any }>> {
  const limit = opts.limit ?? 100;
  let sql = `
    SELECT DISTINCT li.seq, s.value
    FROM log_index li
    JOIN state s ON s.room_id = li.room_id
      AND s.scope = '_audit'
      AND s.sort_key = li.seq
    WHERE li.room_id = ? AND li.scope = '_samples' AND li.key = ?
  `;
  const args: any[] = [roomId, viewId];

  if (opts.after) {
    sql += ` AND li.seq > ?`;
    args.push(opts.after);
  }

  sql += ` ORDER BY li.seq ASC LIMIT ?`;
  args.push(limit);

  const result = await sqlite.execute({ sql, args });
  return result.rows.map(([seq, rawValue]) => {
    let entry: any = {};
    try { entry = JSON.parse(rawValue as string); } catch {}
    return {
      seq: seq as number,
      ts: entry.ts ?? "",
      value: entry.views?.[viewId] ?? null,
    };
  });
}

/**
 * meta.ts — Entry metadata computation for wrapped state.
 *
 * v9: Every state entry carries { value, _meta: { ... } }.
 * This module computes _meta from:
 *   - The state row itself (revision, updated_at)
 *   - A single bulk audit scan (writer, via, seq, velocity, writers, first_at)
 *   - Action invocation stats (invocations, last_invoked_at, last_invoked_by)
 *   - Contested targets (contested)
 *   - Agent-specific salience score
 *
 * Design principle: one SQL query for audit entries, one pass to accumulate
 * per-key stats. Room-level meta is agent-independent. Score is added per-agent.
 *
 * Replaces salience.ts — score becomes one field in _meta, not a separate module.
 */

import { sqlite } from "https://esm.town/v/std/sqlite";
import type { DependencySet } from "./deps.ts";
import { isRelevant } from "./deps.ts";

// ── Types ──────────────────────────────────────────────────────────────

export interface EntryMeta {
  revision: number;
  updated_at: string;
  writer: string | null;
  via: string | null;
  seq: number | null;
  score: number;
  velocity: number;
  writers: string[];
  first_at: string | null;
  elided: boolean;
}

export interface ActionMeta extends EntryMeta {
  invocations: number;
  last_invoked_at: string | null;
  last_invoked_by: string | null;
  contested: string[];
}

export interface WrappedEntry<T = any> {
  value: T;
  _meta: EntryMeta | ActionMeta;
}

// ── Internal accumulators ──────────────────────────────────────────────

interface WriteEvent {
  agent: string;
  action: string;
  seq: number;
  ts: string;
}

interface KeyAccum {
  writes: WriteEvent[];
  earliest_ts: string | null;
}

interface ActionInvokeAccum {
  invocations: number;
  last_invoked_at: string | null;
  last_invoked_by: string | null;
}

// ── Velocity ───────────────────────────────────────────────────────────

const VELOCITY_HALF_LIFE_MS = 300_000; // 5 minutes

/**
 * Exponential-decay weighted write count.
 * A write just now contributes 1.0, a write 5 min ago contributes 0.5.
 * Dimensionless — higher = more recent write activity.
 */
function computeVelocity(writes: WriteEvent[], now: number): number {
  let sum = 0;
  for (const w of writes) {
    const ts = new Date(w.ts).getTime();
    if (isNaN(ts)) continue;
    const age = now - ts;
    if (age < 0) continue;
    sum += Math.pow(0.5, age / VELOCITY_HALF_LIFE_MS);
  }
  return Math.round(sum * 100) / 100;
}

// ── Room-level meta (agent-independent) ────────────────────────────────

export interface RoomMeta {
  keys: Map<string, {
    writer: string | null;
    via: string | null;
    seq: number | null;
    velocity: number;
    writers: string[];
    first_at: string | null;
  }>;
  actions: Map<string, ActionInvokeAccum>;
  /** Contested write targets: "scope:key" → list of competing action IDs */
  contested: Map<string, string[]>;
}

/**
 * Compute room-level metadata from a single bulk audit scan.
 * One query, one pass. Agent-independent — score is added later.
 */
export async function computeRoomMeta(roomId: string): Promise<RoomMeta> {
  const now = Date.now();

  // ── Single audit scan ──
  const auditResult = await sqlite.execute({
    sql: `SELECT sort_key, value FROM state
          WHERE room_id = ? AND scope = '_audit'
          ORDER BY sort_key DESC LIMIT 1000`,
    args: [roomId],
  });

  const keyAccums = new Map<string, KeyAccum>();
  const actionAccums = new Map<string, ActionInvokeAccum>();

  for (const row of auditResult.rows) {
    const seq = Number(row[0]);
    let entry: any;
    try { entry = JSON.parse(row[1] as string); } catch { continue; }

    const agent = entry.agent ?? "";
    const action = entry.action ?? "";
    const ts = entry.ts ?? "";

    // Track action invocations (only non-builtin successful invokes)
    if ((entry.kind === "invoke" || (!entry.kind && entry.action)) && entry.ok !== false) {
      if (action && !entry.builtin) {
        let accum = actionAccums.get(action);
        if (!accum) {
          accum = { invocations: 0, last_invoked_at: null, last_invoked_by: null };
          actionAccums.set(action, accum);
        }
        accum.invocations++;
        // First encountered in DESC order = most recent
        if (!accum.last_invoked_at) {
          accum.last_invoked_at = ts;
          accum.last_invoked_by = agent;
        }
      }
    }

    // Track per-key writes
    const writes: Array<{ scope: string; key: string }> = entry.effect?.writes ?? [];
    for (const w of writes) {
      if (!w.scope || !w.key) continue;
      const mk = `${w.scope}:${w.key}`;
      let accum = keyAccums.get(mk);
      if (!accum) {
        accum = { writes: [], earliest_ts: null };
        keyAccums.set(mk, accum);
      }
      accum.writes.push({ agent, action, seq, ts });
      // Last seen in DESC order = earliest known
      accum.earliest_ts = ts;
    }
  }

  // ── Compute per-key derived fields ──
  const keys = new Map<string, {
    writer: string | null; via: string | null; seq: number | null;
    velocity: number; writers: string[]; first_at: string | null;
  }>();

  for (const [mk, accum] of keyAccums) {
    const mostRecent = accum.writes[0]; // first in DESC = most recent
    const writerSet = [...new Set(accum.writes.map(w => w.agent))];
    keys.set(mk, {
      writer: mostRecent?.agent ?? null,
      via: mostRecent?.action ?? null,
      seq: mostRecent?.seq ?? null,
      velocity: computeVelocity(accum.writes, now),
      writers: writerSet,
      first_at: accum.earliest_ts,
    });
  }

  // ── Contested targets from action definitions ──
  const contested = new Map<string, string[]>();
  try {
    const actionsResult = await sqlite.execute({
      sql: `SELECT key, value FROM state WHERE room_id = ? AND scope = '_actions'`,
      args: [roomId],
    });
    const writeTargets = new Map<string, string[]>();
    for (const row of actionsResult.rows) {
      const actionId = row[0] as string;
      try {
        const def = JSON.parse(row[1] as string);
        if (!Array.isArray(def.writes)) continue;
        for (const w of def.writes) {
          const scope = w.scope ?? "_shared";
          const key = w.key;
          if (!key || key.includes("${")) continue; // skip templated keys
          const target = `${scope}:${key}`;
          if (!writeTargets.has(target)) writeTargets.set(target, []);
          writeTargets.get(target)!.push(actionId);
        }
      } catch {}
    }
    for (const [target, actions] of writeTargets) {
      if (actions.length >= 2) contested.set(target, actions);
    }
  } catch {}

  return { keys, actions: actionAccums, contested };
}

// ── Score computation (agent-specific) ─────────────────────────────────

export interface ScoreWeights {
  recency: number;
  dependency: number;
  authorship: number;
  directed: number;
  contest: number;
  delta: number;
}

export const DEFAULT_WEIGHTS: ScoreWeights = {
  recency: 0.10,
  dependency: 0.30,
  authorship: 0.10,
  directed: 0.20,
  contest: 0.10,
  delta: 0.20,
};

/** Agent-specific context needed for score computation */
export interface AgentContext {
  agentId: string;
  deps: DependencySet;
  lastSeen: string | null;
  registeredActions: Set<string>;
  weights: ScoreWeights;
}

/**
 * Load the agent context needed for score computation.
 * One function, two queries.
 */
export async function loadAgentContext(
  roomId: string,
  agentId: string,
  stateRows: any[],
): Promise<AgentContext> {
  // Agent last_heartbeat from _agents scope (already in stateRows)
  let lastSeen: string | null = null;
  const agentRow = stateRows.find(
    (r: any) => r.scope === "_agents" && r.key === agentId,
  );
  if (agentRow) {
    try {
      const val = JSON.parse(agentRow.value);
      lastSeen = val.last_heartbeat ?? null;
    } catch {}
  }

  // Agent's registered actions (from stateRows)
  const registeredActions = new Set<string>();
  for (const row of stateRows) {
    if (row.scope !== "_actions") continue;
    try {
      const def = JSON.parse(row.value);
      if (def.registered_by === agentId) registeredActions.add(row.key);
    } catch {}
  }

  // Agent's view dependencies (from stateRows)
  const deps: DependencySet = [];
  for (const row of stateRows) {
    if (row.scope !== "_views") continue;
    try {
      const viewDef = JSON.parse(row.value);
      if (
        viewDef.registered_by === agentId || viewDef.scope === agentId
      ) {
        if (Array.isArray(viewDef.deps)) {
          deps.push(...viewDef.deps);
        }
      }
    } catch {}
  }

  // Room-level weight overrides
  let weights = { ...DEFAULT_WEIGHTS };
  const configRow = stateRows.find(
    (r: any) => r.scope === "_config" && r.key === "salience_weights",
  );
  if (configRow) {
    try {
      const overrides = JSON.parse(configRow.value);
      weights = { ...weights, ...overrides };
    } catch {}
  }

  return { agentId, deps, lastSeen, registeredActions, weights };
}

/**
 * Compute salience score for a single entry.
 * All signals normalized to [0, 1], weighted sum.
 */
export function computeScore(
  scope: string,
  key: string,
  updatedAt: string | null,
  value: any,
  agentCtx: AgentContext | null,
  roomMeta: RoomMeta,
): number {
  if (!agentCtx) return 0.5; // no agent context → neutral score

  const w = agentCtx.weights;
  const now = Date.now();
  const mk = `${scope}:${key}`;

  // Recency: exponential decay from last update
  let recency = 0;
  if (updatedAt) {
    const age = now - new Date(updatedAt).getTime();
    if (age >= 0) recency = Math.pow(0.5, age / 300_000);
  }

  // Dependency: is this key in the agent's view dependency set?
  const dependency = isRelevant(agentCtx.deps, scope, key) ? 1.0 : 0;

  // Authorship: did this agent last write this key?
  const km = roomMeta.keys.get(mk);
  const authorship = km?.writer === agentCtx.agentId ? 1.0 : 0;

  // Directed: for messages, is this directed at the agent?
  let directed = 0;
  if (scope === "_messages" && typeof value === "object" && value !== null) {
    if (Array.isArray(value.to)) {
      directed = value.to.includes(agentCtx.agentId) ? 1.0 : 0.1;
    } else {
      directed = 0.3; // broadcast
    }
  }

  // Contest: is this key a write target of 2+ actions?
  let contest = 0;
  const contestants = roomMeta.contested.get(mk);
  if (contestants && contestants.length >= 2) {
    contest = contestants.some((id) => agentCtx.registeredActions.has(id))
      ? 1.0
      : 0.5;
  }

  // Delta: has this key been updated since the agent's last heartbeat?
  let delta = 0;
  if (updatedAt && agentCtx.lastSeen) {
    const updated = new Date(updatedAt).getTime();
    const last = new Date(agentCtx.lastSeen).getTime();
    if (!isNaN(updated) && !isNaN(last) && updated > last) delta = 1.0;
  }

  const score = recency * w.recency +
    dependency * w.dependency +
    authorship * w.authorship +
    directed * w.directed +
    contest * w.contest +
    delta * w.delta;

  return Math.round(score * 100) / 100;
}

// ── Entry wrapping ─────────────────────────────────────────────────────

/**
 * Wrap a state entry with full _meta.
 * Called once per entry during buildContext.
 */
export function wrapEntry(
  value: any,
  scope: string,
  key: string,
  revision: number,
  updatedAt: string,
  roomMeta: RoomMeta,
  score: number,
): WrappedEntry {
  const mk = `${scope}:${key}`;
  const km = roomMeta.keys.get(mk);

  const meta: EntryMeta = {
    revision,
    updated_at: updatedAt,
    writer: km?.writer ?? null,
    via: km?.via ?? null,
    seq: km?.seq ?? null,
    score,
    velocity: km?.velocity ?? 0,
    writers: km?.writers ?? [],
    first_at: km?.first_at ?? null,
    elided: false,
  };

  // Action-specific meta
  if (scope === "_actions") {
    const am = roomMeta.actions.get(key);
    // Contested: other actions that share write targets with this action
    const myContested: string[] = [];
    for (const [_target, actions] of roomMeta.contested) {
      if (actions.includes(key)) {
        for (const a of actions) {
          if (a !== key && !myContested.includes(a)) myContested.push(a);
        }
      }
    }

    const actionMeta = meta as ActionMeta;
    actionMeta.invocations = am?.invocations ?? 0;
    actionMeta.last_invoked_at = am?.last_invoked_at ?? null;
    actionMeta.last_invoked_by = am?.last_invoked_by ?? null;
    actionMeta.contested = myContested;
  }

  return { value, _meta: meta };
}

/**
 * Create a minimal _meta for entries with no audit history.
 * Used for newly created entries or entries predating the audit window.
 */
export function minimalMeta(
  revision: number,
  updatedAt: string,
  score: number = 0,
): EntryMeta {
  return {
    revision,
    updated_at: updatedAt,
    writer: null,
    via: null,
    seq: null,
    score,
    velocity: 0,
    writers: [],
    first_at: null,
    elided: false,
  };
}

/**
 * deps.ts — CEL dependency extraction.
 *
 * Verified against @marcbachmann/cel-js AST output (March 2026).
 *
 * AST format:
 *   { op: "id", args: "state" }               — identifier (args is a STRING)
 *   { op: ".", args: [parent, "field"] }       — member access
 *   { op: "[]", args: [obj, index] }           — bracket access
 *   { op: "value", args: "literal" }           — literal value
 *   { op: "==", args: [left, right] }          — comparison
 *   { op: "?:", args: [cond, then, else] }     — ternary
 *   { op: "&&", args: [left, right] }          — logical and
 *
 * CRITICAL: Pipe expressions (state._shared | keys() | filter(...))
 * are NOT parseable by parse() — they fail with "Unexpected character: |".
 * evaluate() handles them at runtime but the AST is unavailable.
 * For pipe expressions, we fall back to regex extraction.
 *
 * Strategy:
 *   1. Try AST walking (covers direct access, bracket access, comparisons)
 *   2. Fall back to regex for pipe expressions and parse failures
 *   3. Complement with Proxy tracing at runtime (optional validation)
 */

import { parse } from "npm:@marcbachmann/cel-js";

// ── Types ──────────────────────────────────────────────────────────────

export interface Dependency {
  root: "state" | "views" | "agents" | "actions" | "messages";
  scope?: string;
  key?: string;
  prefix?: string;
  access: "direct" | "scope" | "prefix" | "full";
  certainty: "static" | "regex" | "runtime";
}

export type DependencySet = Dependency[];

// ── Context roots ──────────────────────────────────────────────────────

const CONTEXT_ROOTS = new Set(["state", "views", "agents", "actions", "messages"]);

// ── AST Walking (verified format) ──────────────────────────────────────

/**
 * Resolve a member access chain from an AST node.
 * Returns ["state", "_shared", "phase"] for state._shared.phase
 */
function resolveChain(node: any): string[] | null {
  if (!node || typeof node !== "object") return null;

  // Identifier: { op: "id", args: "state" }
  if (node.op === "id" && typeof node.args === "string") {
    return [node.args];
  }

  // Member access: { op: ".", args: [parent, "field"] }
  if (node.op === "." && Array.isArray(node.args) && node.args.length === 2) {
    const parent = resolveChain(node.args[0]);
    const field = node.args[1];
    if (parent && typeof field === "string") {
      return [...parent, field];
    }
    return null;
  }

  // Bracket access: { op: "[]", args: [obj, { op: "value", args: "key" }] }
  if (node.op === "[]" && Array.isArray(node.args) && node.args.length === 2) {
    const parent = resolveChain(node.args[0]);
    const index = node.args[1];
    if (parent && index?.op === "value" && typeof index.args === "string") {
      return [...parent, index.args];
    }
    return null;
  }

  return null;
}

/**
 * Walk an AST and extract dependencies.
 * Only records the MOST SPECIFIC dep per chain (direct > scope > full).
 */
function walkAst(node: any, deps: Dependency[], seen: Set<string>) {
  if (!node || typeof node !== "object") return;

  function addDep(dep: Dependency) {
    const k = JSON.stringify(dep);
    if (seen.has(k)) return;
    seen.add(k);
    deps.push(dep);
  }

  // Find the deepest resolvable chain at this node.
  // We want state._shared.phase to produce ONE dep (direct), not three.
  function deepestChain(n: any): string[] | null {
    // Try to extend: if this is a "." with a child that's also a ".",
    // the parent will be covered by the child's walk. So only resolve
    // at leaf positions (nodes not used as operands in a deeper ".").
    const chain = resolveChain(n);
    return chain;
  }

  // Check if this node is a leaf in a member chain (not the operand of a parent ".")
  // We handle this by only recording deps for the TOP-LEVEL chain at each point.
  const chain = deepestChain(node);
  if (chain && chain.length > 0 && CONTEXT_ROOTS.has(chain[0])) {
    const root = chain[0] as Dependency["root"];
    if (root === "state") {
      if (chain.length >= 3) {
        addDep({ root: "state", scope: chain[1], key: chain[2], access: "direct", certainty: "static" });
      } else if (chain.length === 2) {
        addDep({ root: "state", scope: chain[1], access: "scope", certainty: "static" });
      } else {
        addDep({ root: "state", access: "full", certainty: "static" });
      }
    } else {
      if (chain.length >= 2) {
        addDep({ root, key: chain[1], access: "direct", certainty: "static" });
      } else {
        addDep({ root, access: "scope", certainty: "static" });
      }
    }
    // For member chains, DON'T recurse into children — the chain
    // already captured the full access path. Recurse into non-chain
    // siblings (e.g. the right side of a comparison).
    if (node.op === "." || node.op === "[]") return;
  }

  // Not a resolvable chain — recurse into args
  if (Array.isArray(node.args)) {
    for (const arg of node.args) {
      if (arg && typeof arg === "object") walkAst(arg, deps, seen);
    }
  }
}

// ── Regex Fallback (for pipe expressions) ──────────────────────────────

/**
 * Extract dependencies from a CEL expression string using regex.
 * Used when AST parsing fails (pipe expressions) or as a supplement.
 */
function extractRegex(expr: string): Dependency[] {
  const deps: Dependency[] = [];
  const seen = new Set<string>();

  function addDep(dep: Dependency) {
    const k = JSON.stringify(dep);
    if (seen.has(k)) return;
    seen.add(k);
    deps.push(dep);
  }

  // Direct key access: state._shared.phase or state._shared.theses.x
  const directPattern = /state\.([a-zA-Z_][a-zA-Z0-9_]*)\.([a-zA-Z_][a-zA-Z0-9_]*)/g;
  let m;
  while ((m = directPattern.exec(expr))) {
    addDep({ root: "state", scope: m[1], key: m[2], access: "direct", certainty: "regex" });
  }

  // Scope-level access: state._shared (without further key, e.g. in pipe chains)
  const scopePattern = /state\.([a-zA-Z_][a-zA-Z0-9_]*)\s*[|)]/g;
  while ((m = scopePattern.exec(expr))) {
    addDep({ root: "state", scope: m[1], access: "scope", certainty: "regex" });
  }

  // Bracket access: state._shared["key.with.dots"]
  const bracketPattern = /state\.([a-zA-Z_][a-zA-Z0-9_]*)\["([^"]+)"\]/g;
  while ((m = bracketPattern.exec(expr))) {
    addDep({ root: "state", scope: m[1], key: m[2], access: "direct", certainty: "regex" });
  }

  // startsWith patterns: k.startsWith("concepts.")
  const prefixPattern = /startsWith\(["']([^"']+)["']\)/g;
  while ((m = prefixPattern.exec(expr))) {
    addDep({ root: "state", prefix: m[1], access: "prefix", certainty: "regex" });
  }

  // View references: views["concept_count"] or views.concept_count
  const viewPattern1 = /views\["([^"]+)"\]/g;
  while ((m = viewPattern1.exec(expr))) {
    addDep({ root: "views", key: m[1], access: "direct", certainty: "regex" });
  }
  const viewPattern2 = /views\.([a-zA-Z_][a-zA-Z0-9_]*)/g;
  while ((m = viewPattern2.exec(expr))) {
    addDep({ root: "views", key: m[1], access: "direct", certainty: "regex" });
  }

  // Agent/action references
  const agentPattern = /agents\.([a-zA-Z_][a-zA-Z0-9_]*)/g;
  while ((m = agentPattern.exec(expr))) {
    addDep({ root: "agents", key: m[1], access: "direct", certainty: "regex" });
  }

  // Messages reference
  if (/messages\b/.test(expr)) {
    addDep({ root: "messages", access: "scope", certainty: "regex" });
  }

  // Bare "agents" or "actions" in pipe chains
  if (/\bagents\s*[|.]/.test(expr) || /\bagents\s*\|/.test(expr)) {
    addDep({ root: "agents", access: "full", certainty: "regex" });
  }
  if (/\bactions\s*[|.]/.test(expr) || /\bactions\s*\|/.test(expr)) {
    addDep({ root: "actions", access: "full", certainty: "regex" });
  }

  return deps;
}

// ── Main extraction ────────────────────────────────────────────────────

/**
 * Extract dependencies from a CEL expression.
 *
 * Tries AST walking first (accurate, handles member access chains).
 * Falls back to regex for pipe expressions (which fail to parse).
 * Returns a deduplicated array.
 */
export function extractDependencies(expr: string): DependencySet {
  const deps: Dependency[] = [];
  const seen = new Set<string>();

  // Try AST walking
  let astWorked = false;
  try {
    const compiled = parse(expr);
    if (compiled?.ast) {
      walkAst(compiled.ast, deps, seen);
      astWorked = true;
    }
  } catch {
    // Parse failed (likely pipe expression) — fall through to regex
  }

  // Always run regex to catch pipe expressions and supplement AST
  const regexDeps = extractRegex(expr);
  for (const dep of regexDeps) {
    const k = JSON.stringify({ ...dep, certainty: undefined });
    // Only add regex deps that aren't already covered by AST deps
    const hasStatic = deps.some(d => {
      const dk = JSON.stringify({ ...d, certainty: undefined });
      return dk === k;
    });
    if (!hasStatic) {
      const fullK = JSON.stringify(dep);
      if (!seen.has(fullK)) {
        seen.add(fullK);
        deps.push(dep);
      }
    }
  }

  return deps;
}

// ── Proxy Tracing ──────────────────────────────────────────────────────

/**
 * Wrap a CEL context in Proxies that record property access.
 * Use to validate/supplement extracted dependencies at runtime.
 */
export function traceContext(ctx: Record<string, any>): {
  traced: Record<string, any>;
  getAccesses: () => DependencySet;
} {
  const accesses: Array<{ path: string[] }> = [];

  function proxyWrap(obj: any, path: string[]): any {
    if (obj === null || typeof obj !== "object") return obj;
    if (typeof obj === "function") return obj;

    return new Proxy(obj, {
      get(target, prop, receiver) {
        if (typeof prop === "symbol") return Reflect.get(target, prop, receiver);
        const key = String(prop);
        if (key === "toJSON" || key === "constructor" || key === "prototype" ||
            key === "then" || key === "length" || key === "toString" || key === "valueOf") {
          return Reflect.get(target, prop, receiver);
        }
        accesses.push({ path: [...path, key] });
        const val = Reflect.get(target, prop, receiver);
        return proxyWrap(val, [...path, key]);
      },
    });
  }

  function getAccesses(): DependencySet {
    const deps: Dependency[] = [];
    const seen = new Set<string>();
    for (const { path } of accesses) {
      if (path.length === 0 || !CONTEXT_ROOTS.has(path[0])) continue;
      const root = path[0] as Dependency["root"];
      let dep: Dependency;
      if (root === "state") {
        if (path.length >= 3) dep = { root: "state", scope: path[1], key: path[2], access: "direct", certainty: "runtime" };
        else if (path.length === 2) dep = { root: "state", scope: path[1], access: "scope", certainty: "runtime" };
        else dep = { root: "state", access: "full", certainty: "runtime" };
      } else {
        dep = { root, key: path.length >= 2 ? path[1] : undefined, access: path.length >= 2 ? "direct" : "scope", certainty: "runtime" };
      }
      const k = JSON.stringify(dep);
      if (!seen.has(k)) { seen.add(k); deps.push(dep); }
    }
    return deps;
  }

  return { traced: proxyWrap(ctx, []), getAccesses };
}

// ── Utilities ──────────────────────────────────────────────────────────

export function mergeDependencies(staticDeps: DependencySet, runtimeDeps: DependencySet): DependencySet {
  const seen = new Set<string>();
  const merged: Dependency[] = [];
  for (const dep of staticDeps) {
    const k = JSON.stringify({ ...dep, certainty: undefined });
    if (!seen.has(k)) { seen.add(k); merged.push(dep); }
  }
  for (const dep of runtimeDeps) {
    const k = JSON.stringify({ ...dep, certainty: undefined });
    if (!seen.has(k)) { seen.add(k); merged.push(dep); }
  }
  return merged;
}

export function isRelevant(deps: DependencySet, scope: string, key: string): boolean {
  for (const dep of deps) {
    if (dep.root !== "state") continue;
    if (dep.access === "full") return true;
    if (dep.access === "scope" && dep.scope === scope) return true;
    if (dep.access === "direct" && dep.scope === scope && dep.key === key) return true;
    if (dep.access === "prefix" && dep.prefix && key.startsWith(dep.prefix)) {
      if (!dep.scope || dep.scope === scope) return true;
    }
  }
  return false;
}

// ── Probe (development) ────────────────────────────────────────────────

export function probeAst(expr: string): any {
  try {
    const compiled = parse(expr);
    return compiled.ast;
  } catch (e: any) {
    return { error: e.message };
  }
}
